//! Local CELPIP insight generation.
//!
//! The exam — its parts, MCQ grading and writing/speaking CLB scoring — is a
//! FlexiLingo service and always runs in the cloud. Only the *AI insight* layer
//! has two homes:
//!
//! * **Pro users** get FlexiLingo's insight (`/exam?action=get_insight`), which
//!   uses the same models the web app uses.
//! * **Everyone else** gets an insight generated by the model configured in
//!   Settings (ollama by default). That's the whole point of a desktop app: the
//!   analysis a free web user can't have runs on their own machine.
//!
//! The JSON produced here matches the cloud's `ExamInsight` fragments exactly, so
//! the results UI never learns which one it's rendering.

pub mod prompts;

use serde::{Deserialize, Serialize};

/// The skills an insight can be generated for. `summary` is derived from the
/// others and must run last.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum InsightSkill {
    Listening,
    Reading,
    Writing,
    Speaking,
    Summary,
}

impl InsightSkill {
    pub fn as_str(&self) -> &'static str {
        match self {
            InsightSkill::Listening => "listening",
            InsightSkill::Reading => "reading",
            InsightSkill::Writing => "writing",
            InsightSkill::Speaking => "speaking",
            InsightSkill::Summary => "summary",
        }
    }

    pub fn parse(s: &str) -> Result<Self, String> {
        match s {
            "listening" => Ok(InsightSkill::Listening),
            "reading" => Ok(InsightSkill::Reading),
            "writing" => Ok(InsightSkill::Writing),
            "speaking" => Ok(InsightSkill::Speaking),
            "summary" => Ok(InsightSkill::Summary),
            _ => Err("INVALID_SKILL".to_string()),
        }
    }

    /// MCQ skills produce a different insight shape than the productive skills.
    pub fn is_mcq(&self) -> bool {
        matches!(self, InsightSkill::Listening | InsightSkill::Reading)
    }
}

/// Everything the model needs about one skill, assembled by the frontend from
/// the results payload so this module never has to understand exam content.
#[derive(Debug, Deserialize)]
pub struct SkillContext {
    /// Free-form JSON: wrong answers for MCQ, responses + criteria for W/S.
    pub payload: serde_json::Value,
    /// The CLB the cloud already awarded, so the insight stays consistent with it.
    pub clb_score: Option<f64>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn skill_round_trips_through_its_wire_name() {
        for s in ["listening", "reading", "writing", "speaking", "summary"] {
            assert_eq!(InsightSkill::parse(s).unwrap().as_str(), s);
        }
    }

    #[test]
    fn unknown_skill_is_rejected_with_the_backend_error_code() {
        // The UI resolves this code through i18n, exactly as it does for the cloud.
        assert_eq!(InsightSkill::parse("vocabulary").unwrap_err(), "INVALID_SKILL");
    }

    #[test]
    fn only_listening_and_reading_are_mcq() {
        assert!(InsightSkill::Listening.is_mcq());
        assert!(InsightSkill::Reading.is_mcq());
        assert!(!InsightSkill::Writing.is_mcq());
        assert!(!InsightSkill::Speaking.is_mcq());
        assert!(!InsightSkill::Summary.is_mcq());
    }
}
